/* Fridge and private meal diary. Photos never leave this device. */
window.FridgeUI={install(h){
 const C=window.FridgeCore,$=s=>document.querySelector(s),escape=h.escape;
 const id=()=>crypto.randomUUID();
 const s=()=>h.state();
 function migrate(){C.migrateCondiments(s(),h.canonical);for(const b of s().inventory){if(!b.batchId)b.batchId=id();if(!['冷藏','冷冻','常温'].includes(b.zone))b.zone='冷藏';if(C.days(b.storedOn)===null)b.storedOn=null;if(!Number.isInteger(b.remindDays)||b.remindDays<1)b.remindDays=3;}if(!Array.isArray(s().mealRecords))s().mealRecords=[];}
 migrate();
 const pantry=document.createElement('details');pantry.className='surface condiment-panel';pantry.id='condiment-panel';
 pantry.innerHTML='<summary>常备调味品 <span id="condiment-summary"></span></summary><p class="fridge-note">勾选家里有的，用完再取消；不录数量、不自动扣减。生抽、老抽、酱油分别选择，不相互替代。菜谱仍显示建议用量。</p><div class="condiment-grid"></div>';
 $('#ingredients .pantry-main').prepend(pantry);
 const quick=document.createElement('div');quick.className='fresh-shortcuts';quick.innerHTML='<strong>葱姜蒜 · 常用鲜料</strong><p class="fridge-note">和蔬菜一样按实际数量放入冰箱。</p><div class="quick">'+['葱','姜','蒜','青葱'].map(n=>'<button type="button" data-fresh="'+n+'">'+n+' ＋</button>').join('')+'</div>';
 $('#ingredients .pantry-main > .surface:not(.condiment-panel) .surface-title').after(quick);
 quick.querySelectorAll('[data-fresh]').forEach(b=>b.onclick=()=>{const item=window.ingredientCatalog.find(x=>x.name===b.dataset.fresh);add(item.name,item.qty,item.unit);});
 const nameInput=$('#ingredient-name'),amountInput=$('#ingredient-qty'),unitInput=$('#ingredient-unit');
 const syncManual=()=>{const presence=C.isCondiment(h.canonical(nameInput.value));for(const input of [amountInput,unitInput]){input.disabled=presence;input.required=!presence;input.closest('label').hidden=presence;}$('#ingredient-form button[type=submit]').textContent=presence?'✓ 标记为有':'＋ 添加';};
 nameInput.addEventListener('input',syncManual);$('#ingredient-form').addEventListener('reset',()=>setTimeout(syncManual,0));
 const oldList=$('#inventory');oldList.hidden=true;
 const shell=document.createElement('div');shell.id='fridge-display';oldList.after(shell);
 $('.inventory-surface h2').childNodes[0].textContent='我的冰箱 ';
 const intro=$('#ingredients .page-intro');intro.innerHTML='<h1>打开冰箱，记得好好吃饭。</h1><p>每次放入单独记一批。先用较早放入的食材，把新鲜留给每一顿。</p>';
 const diary=document.createElement('section');diary.className='meal-diary surface';diary.id='meal-diary';$('#plan').append(diary);
 const selectedPlan=document.createElement('section');selectedPlan.id='selected-meal-plan';selectedPlan.setAttribute('aria-label','已选菜单与做饭操作');$('#plan .recipe-controls').before(selectedPlan);
 ['.meal-plan-heading','.plan-toolbar','#meals'].forEach(selector=>selectedPlan.append($('#plan '+selector)));
 selectedPlan.querySelector('h2').textContent='这顿想做的菜';
 selectedPlan.querySelector('.meal-plan-heading p').textContent='先选菜，再跟着做法开始；做完并记录后才扣库存。';
 const controls=document.createElement('div');controls.className='fridge-actions';controls.innerHTML='<button class="button primary" id="start-meal">开始做饭 · 查看做法</button><button class="button primary" id="finish-meal">做完了 · 记录这顿饭</button><button class="button ghost" id="view-diary">我的用餐记录</button>';$('#meals').before(controls);
 $('#start-meal').onclick=()=>{const first=h.plan()[0];if(first)h.openRecipe(first);};
 $('#view-diary').onclick=()=>diary.scrollIntoView({behavior:'smooth'});
 function dialog(html){const d=document.createElement('dialog');d.className='fridge-dialog';d.innerHTML=html;const heading=d.querySelector('h2');if(heading){heading.tabIndex=-1;heading.setAttribute('autofocus','');}document.body.append(d);d.addEventListener('close',()=>d.remove());d.showModal();return d;}
 function change(mutator){h.change(mutator);migrate();h.render();}
 function edit(batch){const fresh=!batch.batchId;const d=dialog(`<form><h2>${fresh?escape(batch.name)+' · 放进冰箱':escape(batch.name)+' · 这批食材'}</h2><p class="fridge-note">每次加入独立记录，不会把旧食材的存放时间重置。</p><label>现有数量（${escape(batch.unit)}）<input name="amount" type="number" min="0.01" max="100000" step="any" required value="${batch.qty}"></label><label>放入日期<input name="date" type="date" max="${C.today()}" value="${batch.storedOn||''}" required></label><label>存放位置<select name="zone">${['冷藏','冷冻','常温'].map(z=>`<option ${z===batch.zone?'selected':''}>${z}</option>`).join('')}</select></label><label>放入多少天后提醒我（自定义）<input name="days" type="number" min="1" max="365" required value="${batch.remindDays||3}"></label><p class="fridge-note">默认 3 天只是整理提醒，不是保质期。请依据包装、存放条件与食材状态判断；常温柜不代表所有食材都适合常温保存。</p><p class="feedback-error" role="alert"></p><div class="fridge-actions"><button type="submit" class="button primary">${fresh?'确认放入':'保存这批食材'}</button><button type="button" data-cancel class="button ghost">取消</button>${fresh?'':'<button type="button" data-delete class="button ghost">移出这批</button>'}</div></form>`);
  const form=d.querySelector('form');form.elements.date.value=batch.storedOn||(fresh?C.today():'');
  d.querySelector('[data-cancel]').onclick=()=>d.close();
  const remove=d.querySelector('[data-delete]');if(remove)remove.onclick=()=>{try{change(next=>{next.inventory=next.inventory.filter(x=>x.batchId!==batch.batchId);});d.close();}catch(e){d.querySelector('[role=alert]').textContent=e.message;}};
  form.onsubmit=e=>{e.preventDefault();try{const amount=Number(form.elements.amount.value),date=form.elements.date.value,days=Number(form.elements.days.value);if(!Number.isFinite(amount)||amount<=0||amount>100000||C.days(date)===null||!Number.isInteger(days)||days<1||days>365)throw Error('请检查数量、日期和提醒天数');change(next=>{const item={...batch,batchId:batch.batchId||id(),qty:amount,storedOn:date,zone:form.elements.zone.value,remindDays:days};if(fresh)next.inventory.push(item);else{const index=next.inventory.findIndex(x=>x.batchId===batch.batchId);if(index<0)throw Error('这批食材已被移除，请重新打开');next.inventory[index]=item;}});d.close();h.toast(fresh?'已放入冰箱':'已更新这批食材');}catch(e){d.querySelector('[role=alert]').textContent=e.message;}};
 }
 function add(name,amount,unit){name=h.canonical(name);if(C.isCondiment(name)){try{change(next=>{if(!next.condiments.includes(name))next.condiments.push(name);});h.toast(name+'已标记为有');return true;}catch(e){h.toast(e.message);return false;}}unit=unit.trim();if(!name||!unit||!Number.isFinite(amount)||amount<=0||amount>100000){h.toast('请填写有效的名称、数量与单位');return false;}edit({name,qty:amount,unit,zone:'冷藏',storedOn:C.today(),remindDays:3});return true;}
 function renderInventory(){migrate();$('#condiment-summary').textContent='已拥有 '+s().condiments.length+' 种 · 点击展开/收起';const grid=pantry.querySelector('.condiment-grid');grid.innerHTML=C.condimentNames.map(n=>'<button type="button" data-condiment="'+escape(n)+'" aria-pressed="'+s().condiments.includes(n)+'"><span>'+escape(n)+'</span><small>'+(s().condiments.includes(n)?'✓ 有':'＋ 没有')+'</small></button>').join('');grid.querySelectorAll('[data-condiment]').forEach(b=>b.onclick=()=>{try{change(next=>{const n=b.dataset.condiment;next.condiments=next.condiments.includes(n)?next.condiments.filter(x=>x!==n):[...next.condiments,n];});}catch(e){h.toast(e.message);}});
 const inventory=s().inventory;$('#inventory-empty').hidden=inventory.length>0;for(const selector of ['#inventory-count','#aside-count','#nav-count'])$(selector).textContent=inventory.length;$('#generate-plan').disabled=!inventory.length;$('.aside-hint').textContent='计划只预留，做完并记录后才扣库存。';
  const due=inventory.filter(x=>C.days(x.storedOn)!==null&&C.days(x.storedOn)>=x.remindDays);
  shell.innerHTML=`${due.length?`<div class="fridge-reminders">有 ${due.length} 批到达你设置的提醒时间：${due.map(x=>escape(x.name)).join('、')}。优先查看，合理安排使用。</div>`:''}<div class="fridge-shell"><div class="fridge-top"><strong>MY LITTLE FRIDGE</strong><span class="fridge-led">${inventory.length} 批食材</span></div>${['冷冻','冷藏','常温'].map(zone=>`<section class="fridge-shelf"><h3>${zone==='冷冻'?'❄ 冷冻室':zone==='冷藏'?'◌ 冷藏室':'▤ 冰箱旁 · 常温柜'}</h3><div class="fridge-batches">${inventory.filter(x=>x.zone===zone).map(x=>{const age=C.days(x.storedOn);return `<button class="fridge-item ${age!==null&&age>=x.remindDays?'due':''}" data-batch="${escape(x.batchId)}"><span class="food-icon" aria-hidden="true">${escape(h.icon(x.name)||'🥣')}</span><strong>${escape(x.name)}</strong><span>${h.fmt(x.qty)} ${escape(x.unit)}</span><small>${age===null?'放入日期待补':age===0?'今天放入':`已放 ${age} 天`}</small><small>${age!==null&&age>=x.remindDays?'到提醒时间 · 优先查看':'点击编辑这批'}</small></button>`;}).join('')||'<p class="fridge-note">这一层还空着，放点食材进来吧。</p>'}</div></section>`).join('')}<p class="fridge-note">按实际位置分类；提醒不是食用安全判断。打开页面时更新，不是后台推送通知。</p></div>`;
  shell.querySelectorAll('[data-batch]').forEach(b=>b.onclick=()=>edit({...s().inventory.find(x=>x.batchId===b.dataset.batch)}));
  document.querySelectorAll('[data-people]').forEach(b=>{const n=Number(b.dataset.people);if(n>2){b.disabled=true;b.title='当前先支持 1–2 人';}else b.setAttribute('aria-pressed',String(n===s().people));});
 }
 function renderDiary(){diary.innerHTML='<h2>餐桌日记</h2><p class="fridge-note">只保存在本机，不自动发布社区。清除浏览器/App 数据会丢失记录。</p>'+((s().mealRecords||[]).map(r=>`<article class="meal-record"><small>${escape(new Date(r.at).toLocaleString('zh-CN'))} · ${r.people} 人份</small><h3>${r.dishes.map(x=>escape(x.name)).join('、')}</h3>${r.feedback.photo?`<img src="${r.feedback.photo}" alt="这顿饭的成品记录">`:''}<div>${[r.feedback.reproduce,r.feedback.taste,...(r.feedback.tags||[])].map(t=>`<span class="fridge-tag">${escape(t)}</span>`).join('')}</div>${r.feedback.note?`<p>${escape(r.feedback.note)}</p>`:''}<details><summary>查看本次扣除</summary>${r.used.map(x=>`<p>${escape(x.name)} ${h.fmt(x.qty)} ${escape(x.unit)}</p>`).join('')}</details><button class="button ghost" data-remove-record="${escape(r.id)}">删除记录（不恢复库存）</button></article>`).join('')||'<p>第一顿值得记住的饭，等你来完成。</p>');
  diary.querySelectorAll('[data-remove-record]').forEach(b=>b.onclick=()=>{const d=dialog('<h2>删除这条用餐记录？</h2><p>照片和评价将一并删除，但不会恢复已经消耗的食材。</p><div class="fridge-actions"><button class="button primary" data-yes>确认删除</button><button class="button ghost" data-no>保留</button></div><p role="alert"></p>');d.querySelector('[data-no]').onclick=()=>d.close();d.querySelector('[data-yes]').onclick=()=>{try{change(next=>{next.mealRecords=next.mealRecords.filter(x=>x.id!==b.dataset.removeRecord);});d.close();}catch(e){d.querySelector('[role=alert]').textContent=e.message;}};});
  $('#finish-meal').disabled=!s().plan.length;
 $('#start-meal').disabled=!s().plan.length||h.plan().some(r=>h.missingTools(r).length)||!C.allocate(s().inventory,h.plan(),s().people,h.sources,s().condiments).ok;
 }
 async function photo(file){if(!file)return '';if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024)throw Error('请选择 10 MB 以下 JPG、PNG 或 WebP 照片');const url=URL.createObjectURL(file);try{const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('照片无法读取，请换一张'));img.src=url;});const canvas=document.createElement('canvas'),scale=Math.min(1,900/Math.max(img.width,img.height));canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/jpeg',.65);if(data.length>400000)throw Error('图片压缩后仍太大，请选择更简单或更小的照片');return data;}finally{URL.revokeObjectURL(url);}}
 function finishMeal(recipeId){
  const selected=h.plan().filter(r=>!recipeId||r.id===recipeId);if(!selected.length)return;const snapshot=JSON.stringify(s()),disk=localStorage.getItem('chileme-v1'),token=id();let photoData='',photoBusy=false;
  const d=dialog(`<form class="meal-review-form"><header class="review-header"><span class="review-eyebrow">MY MEAL JOURNAL · 餐桌日记</span><h2>这一顿，值得记下来。</h2></header><p class="fridge-note">只勾选本次实际做完的菜。保存评价与扣除库存会一起完成；取消不会扣库存。</p><fieldset><legend>本次做完的菜</legend>${selected.map((r,i)=>`<label class="review-choice"><input type="checkbox" name="dish" value="${i}" checked><span>${escape(r.name)}</span></label>`).join('')}</fieldset><div class="fridge-amounts" id="meal-deduction"></div><fieldset><legend>跟着菜谱好复刻吗？（必选）</legend>${['好复刻','一般','难复刻'].map(x=>`<label class="review-choice"><input type="radio" name="reproduce" value="${x}" required><span>${x}</span></label>`).join('')}</fieldset><fieldset><legend>味道怎么样？（必选）</legend>${['味道好','一般','不好吃'].map(x=>`<label class="review-choice"><input type="radio" name="taste" value="${x}" required><span>${x}</span></label>`).join('')}</fieldset><fieldset><legend>还想记下什么？（可多选）</legend>${['制作麻烦','步骤清晰','用时超预期','愿意再做'].map(x=>`<label class="review-choice"><input type="checkbox" name="tag" value="${x}"><span>${x}</span></label>`).join('')}</fieldset><label>成品照片（可选，仅本机保存）<input name="photo" type="file" accept="image/jpeg,image/png,image/webp"></label><img id="meal-photo-preview" hidden alt="成品照片预览"><label>一句话心得（可选）<textarea name="note" maxlength="500" rows="3" placeholder="下次少放一点盐……"></textarea></label><p class="feedback-error" role="alert"></p><div class="fridge-actions"><button type="submit" class="button primary">保存这顿饭并扣库存</button><button type="button" data-cancel class="button ghost">还没做好，取消</button></div></form>`);
  d.classList.add('meal-review-dialog');
  const form=d.querySelector('form'),error=d.querySelector('[role=alert]'),submit=form.querySelector('[type=submit]');
  const chosen=()=>[...form.querySelectorAll('[name=dish]:checked')].map(x=>selected[Number(x.value)]);
  const preview=()=>{const result=C.allocate(s().inventory,chosen(),s().people,h.sources,s().condiments);d.querySelector('#meal-deduction').innerHTML='<strong>按菜谱预计扣除</strong><br>'+result.needs.map(n=>n.presenceOnly?`${escape(n.name)}（常备，不扣数量）`:`${escape(n.name)} ${h.fmt(n.qty)} ${escape(n.unit)}`).join(' · ')+(result.ok?'':`<p>库存不足：${result.missing.map(n=>escape(n.name)).join('、')}。请先调整实际库存；不会扣成负数。</p>`);submit.disabled=!chosen().length||!result.ok||photoBusy;};
  form.querySelectorAll('[name=dish]').forEach(x=>x.onchange=preview);preview();d.querySelector('[data-cancel]').onclick=()=>d.close();
  form.elements.photo.onchange=async()=>{photoBusy=true;error.textContent='正在处理照片…';preview();try{photoData=await photo(form.elements.photo.files[0]);const img=d.querySelector('#meal-photo-preview');img.src=photoData;img.hidden=!photoData;error.textContent='';}catch(e){photoData='';form.elements.photo.value='';d.querySelector('#meal-photo-preview').hidden=true;error.textContent=e.message;}finally{photoBusy=false;preview();}};
  form.onsubmit=async e=>{e.preventDefault();if(photoBusy)return;submit.disabled=true;try{const save=()=>{if(JSON.stringify(s())!==snapshot||localStorage.getItem('chileme-v1')!==disk)throw Error('库存或计划已在其他操作中变化，请关闭后重新确认');const dishes=chosen();if(dishes.some(r=>h.missingTools(r).length))throw Error('厨具已变化，请检查计划');const feedback={reproduce:form.elements.reproduce.value,taste:form.elements.taste.value,tags:[...form.querySelectorAll('[name=tag]:checked')].map(x=>x.value),note:form.elements.note.value.trim(),photo:photoData};h.commit(C.finish(s(),dishes,feedback,h.sources,token));};if(navigator.locks)await navigator.locks.request('chileme-finish',save);else save();d.close();h.render();h.toast('这顿饭已记录，库存已扣除');diary.scrollIntoView({behavior:'smooth'});}catch(e){error.textContent=e.message;submit.disabled=false;}};
 };
 window.addEventListener('focus',()=>renderInventory());
 $('#finish-meal').onclick=()=>finishMeal();
 return {add,renderInventory,renderDiary,finishFor:finishMeal};
}};
